<?php
session_start();require_once '../config/database.php';require_once 'lib.php';if(!isset($_SESSION['user_id'])){header('Location: ../login.php');exit;}$railroad=ttOperationsRailroad($pdo,(int)$_SESSION['user_id']);
if($_SERVER['REQUEST_METHOD']==='POST'){try{ttOperationsRequireCsrf();$pdo->beginTransaction();$number=ttNextScopedNumber($pdo,'operating_sessions','session_number',(int)$railroad['id'],'S',5);$name=substr(trim((string)($_POST['session_name']??'')),0,120);$date=(string)($_POST['operating_date']??date('Y-m-d'));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))throw new RuntimeException('Choose a valid operating date.');$stmt=$pdo->prepare('INSERT INTO operating_sessions(railroad_id,created_by_user_id,session_number,session_name,operating_date,notes) VALUES(?,?,?,?,?,?)');$stmt->execute([(int)$railroad['id'],(int)$_SESSION['user_id'],$number,$name?:null,$date,substr(trim((string)($_POST['notes']??'')),0,5000)]);$id=(int)$pdo->lastInsertId();$pdo->commit();header('Location: session_edit.php?id='.$id);exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}
$stmt=$pdo->prepare("SELECT s.*,COUNT(a.id) assignment_count,SUM(a.status='completed') completed_count FROM operating_sessions s LEFT JOIN operation_assignments a ON a.session_id=s.id WHERE s.railroad_id=? GROUP BY s.id ORDER BY s.operating_date DESC,s.id DESC");$stmt->execute([(int)$railroad['id']]);$sessions=$stmt->fetchAll(PDO::FETCH_ASSOC);
?>
<?php include '../includes/header.php';?><title>Operating Sessions</title><link rel="stylesheet" href="../assets/css/operations.css"></head><body><?php include '../includes/navbar.php';?><div class="tt-operations-shell"><?php include '../assets/components/sidebar.php';?><section class="tt-ops-page"><div class="d-flex flex-wrap justify-content-between align-items-end gap-3 mb-4"><div><p class="tt-eyebrow">Operations</p><h1>Operating Sessions</h1><p class="text-muted">Saved operating events with one or more work assignments.</p></div><button class="btn btn-primary" data-bs-toggle="collapse" data-bs-target="#newSession">New Session</button></div>
<?php if(isset($error)):?><div class="alert alert-danger"><?=ttHtml($error)?></div><?php endif;?><div class="collapse mb-4" id="newSession"><div class="card card-body"><form method="post" class="row g-3"><input type="hidden" name="csrf_token" value="<?=ttHtml(ttOperationsCsrfToken())?>"><div class="col-md-5"><label class="form-label">Session Name <span class="text-muted">(optional)</span></label><input class="form-control" name="session_name" maxlength="120"></div><div class="col-md-3"><label class="form-label">Operating Date</label><input class="form-control" type="date" name="operating_date" value="<?=date('Y-m-d')?>" required></div><div class="col-12"><label class="form-label">Notes</label><textarea class="form-control" name="notes" rows="2"></textarea></div><div><button class="btn btn-success">Create Session</button></div></form></div></div>
<div class="card"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Session</th><th>Date</th><th>Assignments</th><th>Status</th><th>Updated</th></tr></thead><tbody><?php foreach($sessions as $session):?><tr><td><a href="session_edit.php?id=<?=(int)$session['id']?>"><strong><?=ttHtml($session['session_number'])?></strong></a><div class="small text-muted"><?=ttHtml($session['session_name'])?></div></td><td><?=ttHtml($session['operating_date'])?></td><td><?=(int)$session['assignment_count']?></td><td><span class="badge tt-status-<?=ttHtml($session['status'])?>"><?=ttHtml(ucwords(str_replace('_',' ',$session['status'])))?></span></td><td><?=ttHtml($session['updated_at'])?></td></tr><?php endforeach;?><?php if(!$sessions):?><tr><td colspan="5" class="text-center text-muted py-5">Create the first operating session.</td></tr><?php endif;?></tbody></table></div></div></section></div><?php include '../includes/footer.php';?>
